window.GuaData = window.GuaData || {}; window.GuaData.artwork = {"1":{"hexagramNumber":1,"typeKey":"ENTJ-calm-autonomous","title":"開途定向者","src":"./assets/personality/hexagram-01.webp","width":1254,"height":1254,"conceptZh":"先擬好遠方的路徑，也願意停下來等同行者；以高天空間表現乾的力量與節奏。","sha256":"ad247b8779787ff0dafcfc96068f7c2027991166de2255befc85fb060a4bb57f"},"2":{"hexagramNumber":2,"typeKey":"ISFJ-calm-cooperative","title":"厚土共育者","src":"./assets/personality/hexagram-02.webp","width":1254,"height":1254,"conceptZh":"兩人先商量再共同移植幼苗，兩個同樣大小的水杯提醒照料也要包含自己；坤的厚土不是單向犧牲。","sha256":"8cd8e7963e4153bb36537afa11122281bb85287266f145497d517797b2a8c4d2"},"3":{"hexagramNumber":3,"typeKey":"ESTP-sensitive-autonomous","title":"雨中拓路者","src":"./assets/personality/hexagram-03.webp","width":1254,"height":1254,"conceptZh":"雨中只先鋪出第一小段路，旁邊的新芽呼應屯的初生；情緒鮮明仍可採用可回退的小試驗。","sha256":"c9d76a6093b95ba365668f3b8ba84efbed706072e591a5926bcb44faae35e52d"},"4":{"hexagramNumber":4,"typeKey":"INTP-sensitive-autonomous","title":"泉問探理者","src":"./assets/personality/hexagram-04.webp","width":1254,"height":1254,"conceptZh":"獨自在山泉旁以葉片做小實驗，把心中的好問題放回現場驗證；蒙代表學習而不是愚昧。","sha256":"75e0f02101c8325a64c6151dc1d97f8e9596812f62992edc6b2b4087cceb3956"},"5":{"hexagramNumber":5,"typeKey":"ESTP-calm-autonomous","title":"候潮行動者","src":"./assets/personality/hexagram-05.webp","width":1254,"height":1254,"conceptZh":"先整理好船與工具，在岸邊觀察水勢；需的等待是一種準備，不是消極停滯。","sha256":"8790d8bd57275cad7a64a645550e9cbb679c5d635b252be9ad31d4140154f7d9"},"6":{"hexagramNumber":6,"typeKey":"ESTJ-sensitive-autonomous","title":"明界議事者","src":"./assets/personality/hexagram-06.webp","width":1254,"height":1254,"conceptZh":"以不同水路與桌面邊界呈現規則和事實待澄清；訟不是好辯的標籤，而是先說清共同約定。","sha256":"86544f36d062c88be4cb6db34cb1a2033bb1bb40eec2429b7e39ba9777e23eb5"},"7":{"hexagramNumber":7,"typeKey":"ENTJ-calm-cooperative","title":"整隊共進者","src":"./assets/personality/hexagram-07.webp","width":1254,"height":1254,"conceptZh":"兩位同等位置的夥伴先對齊模組橋的接點；師的群體紀律轉成能共同承擔的步伐，避開軍事威權。","sha256":"c8872bb80b39731bf94985a8c07ec98a5ce3b1ffb9c8347652fa1a31efa80bbb"},"8":{"hexagramNumber":8,"typeKey":"ESFJ-calm-cooperative","title":"結伴安居者","src":"./assets/personality/hexagram-08.webp","width":1254,"height":1254,"conceptZh":"共同討論庭院水路與座位，入口保持敞開；比的歸屬來自互相選擇，也容得下不同步調。","sha256":"0372aeb4b08652bc537dcf778f87edcbe2c690add8a095f860ac79f8138d7831"},"9":{"hexagramNumber":9,"typeKey":"ESTP-calm-cooperative","title":"聚風蓄勢者","src":"./assets/personality/hexagram-09.webp","width":1254,"height":1254,"conceptZh":"共同製作小風車、保留已完成零件，在密雲下慢慢蓄勢；小畜以可留下的小成果支持大計畫。","sha256":"ad2e199783855fb1d140f2f9c7075ab1e7925710f65cdd2f99b62f8291be7640"},"10":{"hexagramNumber":10,"typeKey":"ESFJ-calm-autonomous","title":"知禮行路者","src":"./assets/personality/hexagram-10.webp","width":1254,"height":1254,"conceptZh":"獨自確認腳步與距離，在安睡的虎旁保留寬裕空間；履的分寸同時尊重他人與自己的界線。","sha256":"bce27d2b33e3cf1b4891eaa89fa81b5b70fbb17fda3ecf9edbea3c223e89c0f9"},"11":{"hexagramNumber":11,"typeKey":"ESTJ-calm-cooperative","title":"通流築序者","src":"./assets/personality/hexagram-11.webp","width":1254,"height":1254,"conceptZh":"兩人疏通從不同高度而來的灌溉渠，讓資源雙向抵達；泰的順暢需要維護，而非永遠不變。","sha256":"d98817d5e45f8c048bebdad58d4fb6ed6e09a7c61fd8864942c6544796aebea0"},"12":{"hexagramNumber":12,"typeKey":"INFP-calm-autonomous","title":"守心候通者","src":"./assets/personality/hexagram-12.webp","width":1254,"height":1254,"conceptZh":"守住自己的安靜工作室，同時主動打開一扇小窗；否是暫時不通的情境，不是人格注定封閉。","sha256":"2058b1efffd6e23d28c2219f55e2f960a5ea13de558ad5c0a45d3e049c299911"},"13":{"hexagramNumber":13,"typeKey":"ENFJ-calm-cooperative","title":"聚志同行者","src":"./assets/personality/hexagram-13.webp","width":1254,"height":1254,"conceptZh":"兩人帶著不同顏色的布，在原野共同縫成一面不必完全相同的帆；同人重視共同志向與差異。","sha256":"c49d51bead7b54a9b523bdd77664ac5436de25ca353c15b3758676a09deee318"},"14":{"hexagramNumber":14,"typeKey":"ENTP-calm-cooperative","title":"集光開想者","src":"./assets/personality/hexagram-14.webp","width":1254,"height":1254,"conceptZh":"合作收集不同透鏡，也一起選出這次要用的少數組合；大有的豐富需要分享與取捨的容器。","sha256":"c1542e0f03d0123f7d4317937e5db2171a1a1f9acb2a1585b046442ab2760301"},"15":{"hexagramNumber":15,"typeKey":"INFP-calm-cooperative","title":"留白共生者","src":"./assets/personality/hexagram-15.webp","width":1254,"height":1254,"conceptZh":"兩人在低矮山坡同高度工作，一位把自己的石子放進共同構圖；謙的留白不應變成消失。","sha256":"e926bc15e955b5c557b90d20edfa3a40f90674e9e5d2cf40caf39c953a9115d2"},"16":{"hexagramNumber":16,"typeKey":"ESFP-calm-cooperative","title":"和樂鼓動者","src":"./assets/personality/hexagram-16.webp","width":1254,"height":1254,"conceptZh":"先一起確認節奏，再敲響小鼓；豫的歡樂包含準備與休息位置，沒有要求人人都熱烈回應。","sha256":"7d535e2dd5f223f99f897c6cf998f5198cf55cf41c15b0c358129afe31a24312"},"17":{"hexagramNumber":17,"typeKey":"ISFP-calm-cooperative","title":"隨時共作人","src":"./assets/personality/hexagram-17.webp","width":1254,"height":1254,"conceptZh":"兩位工作者共同調整織帶，各自保留不同顏色與轉向；隨是有判準地配合情境，而非盲從。","sha256":"35dfe6c723ec585d5230a0189f0b73d134c9cf562887e77d5c33d1ea1888cf71"},"18":{"hexagramNumber":18,"typeKey":"INTJ-sensitive-cooperative","title":"修本更新者","src":"./assets/personality/hexagram-18.webp","width":1254,"height":1254,"conceptZh":"先共同查看水車真正卡住的根部，再更換磨損零件；蠱的更新兼顧承接者，不把舊物一概否定。","sha256":"131aebf614436c5324f1ef667078aad65ac908d6a3dea9b7cd646e330c1c801a"},"19":{"hexagramNumber":19,"typeKey":"ENFJ-calm-autonomous","title":"近人啟途者","src":"./assets/personality/hexagram-19.webp","width":1254,"height":1254,"conceptZh":"先準備好可調整的矮凳與園徑，仍以敞開手勢等候對方選擇；臨的靠近是一份尊重自主的邀請。","sha256":"a20684c445783cb87e897da9f4c468a2f94f84de9d829fedc2dc9dc5fda4f0de"},"20":{"hexagramNumber":20,"typeKey":"INFJ-calm-autonomous","title":"靜觀織意者","src":"./assets/personality/hexagram-20.webp","width":1254,"height":1254,"conceptZh":"從低平台觀察田野與葉影，再把透鏡放低回到現場；觀的洞見需要接受真實回應，不是神秘讀心。","sha256":"1604d6b2db0cbed21a0e3b060a85dcad871b93264f152741dfc95c5612028eaa"},"21":{"hexagramNumber":21,"typeKey":"ENTP-sensitive-cooperative","title":"辨結通路者","src":"./assets/personality/hexagram-21.webp","width":1254,"height":1254,"conceptZh":"兩人先攤開卡住門道的繩結，再以合宜力度拆解；噬嗑的咬開阻隔轉成公平釐清，避開刑罰畫面。","sha256":"eff2a2567261fd1a53826b74d81fed57c714015e784e9147fa6eed9de84d949f"},"22":{"hexagramNumber":22,"typeKey":"ISFP-sensitive-autonomous","title":"映心造境者","src":"./assets/personality/hexagram-22.webp","width":1254,"height":1254,"conceptZh":"獨自製作素器，以簡單布與枝葉襯托真實形狀；賁的美幫助表達，而不是遮住所有內心需要。","sha256":"c869f00b7a37fb375e659f6805ee44e18e2b73be62a3b181f0986301fe63f195"},"23":{"hexagramNumber":23,"typeKey":"INTJ-sensitive-autonomous","title":"去蕪固本者","src":"./assets/personality/hexagram-23.webp","width":1254,"height":1254,"conceptZh":"從老舊棚架卸下失效枝條，保護仍能承重的根與柱；剝的減法指向穩固基礎，而不是一片荒敗。","sha256":"65c2793b1b8cf5ef714bea85a294767e3144d94b0193c8b474692026198a0c16"},"24":{"hexagramNumber":24,"typeKey":"ESFP-calm-autonomous","title":"返真再行者","src":"./assets/personality/hexagram-24.webp","width":1254,"height":1254,"conceptZh":"休息後沿熟悉小徑重新出發，腳邊新芽回應復的循環；回返建立在真正調整，不只是重複耗損。","sha256":"df92a042a0953e47f6d8b52d26fdfb187ba7c04c15b730293a7398c12fe0a2f8"},"25":{"hexagramNumber":25,"typeKey":"ISTP-calm-autonomous","title":"本真試行者","src":"./assets/personality/hexagram-25.webp","width":1254,"height":1254,"conceptZh":"以簡單槓桿實測石塊重量，保留尚未確定的空間；無妄強調貼近事實，也承認偶然不能全被控制。","sha256":"f2148256a88bd99ea2626941e9439c43a372e658b577267fb9d2f94316403ce2"},"26":{"hexagramNumber":26,"typeKey":"INTJ-calm-autonomous","title":"蓄識定局者","src":"./assets/personality/hexagram-26.webp","width":1254,"height":1254,"conceptZh":"從山中小書室帶著一件可試作模型走到外面；大畜的累積與節制，最後需要接受現實檢驗。","sha256":"dae7bbbd529ff2332dedc81606ad1190d6787cbd8feb249b5c6a10b814f0f864"},"27":{"hexagramNumber":27,"typeKey":"ISFJ-calm-autonomous","title":"養心守日者","src":"./assets/personality/hexagram-27.webp","width":1254,"height":1254,"conceptZh":"安排能持續維持的茶食日常，也替自己留下一杯；頤的滋養包含給出與接收，沒有性別角色分配。","sha256":"0ad05055b7116143b72d28cad6445eeed8074101f10a7094c05c62b8bab03786"},"28":{"hexagramNumber":28,"typeKey":"ISTP-sensitive-cooperative","title":"承重共構者","src":"./assets/personality/hexagram-28.webp","width":1254,"height":1254,"conceptZh":"兩位工作者共同為微彎的梁增添支點；大過不是證明誰撐得最多，而是重新分配負荷與資源。","sha256":"0ffddd0e7e9344fab966bcc1d3230483765b8eab10b36fc981de5d3d3b7a7831"},"29":{"hexagramNumber":29,"typeKey":"INFP-sensitive-autonomous","title":"深流守信者","src":"./assets/personality/hexagram-29.webp","width":1254,"height":1254,"conceptZh":"在深水旁只選第一個可行小步，岸上的繩索代表可尋求的支援；坎不是人格命運，而是練習穿越未知。","sha256":"02968f0cc5a31dde6aded5fd56e99c231330e2cca08616cb2d85aee7d5924929"},"30":{"hexagramNumber":30,"typeKey":"ENFJ-sensitive-autonomous","title":"持光引路者","src":"./assets/personality/hexagram-30.webp","width":1254,"height":1254,"conceptZh":"先替手中的燈補充燃料，再照向可步行的路；離的持光需要真實支持，沒有永遠燃燒自己的要求。","sha256":"1d47031fb506369b2a56e86c179995f60acc239d13d7903d727a8664427d3287"},"31":{"hexagramNumber":31,"typeKey":"INFP-sensitive-cooperative","title":"聽心相應者","src":"./assets/personality/hexagram-31.webp","width":1254,"height":1254,"conceptZh":"兩人隔著淺水碗安靜聆聽，保留各自清楚的空間；咸的感應需要詢問與確認，不用讀心或性別配對。","sha256":"6b27b388f1f2f13eebc66c997a26ebd8ba1fe1a3134ab06f5e0ff4eb1bad9c79"},"32":{"hexagramNumber":32,"typeKey":"ISTJ-calm-autonomous","title":"守序長行者","src":"./assets/personality/hexagram-32.webp","width":1254,"height":1254,"conceptZh":"維護循環水輪，旁邊不同生長階段的植株提醒季節變化；恆的長久，是守方向也調整方法。","sha256":"96453e5611dd9b6a74ec8c9e0034927d39226e978c7bbbb0c98b120a9389cda7"},"33":{"hexagramNumber":33,"typeKey":"ISFP-calm-autonomous","title":"留白守山人","src":"./assets/personality/hexagram-33.webp","width":1254,"height":1254,"conceptZh":"山腳的創作者將自己的工作角落留出通風與遠景，折起屏風但不封閉通路。以遯的天山距離表現有意識的界線，保留日後重返交流的入口。","sha256":"28d4808eefe13fbd94b69290e8e34e7959b4dbc955cbc49f621236a206e17582"},"34":{"hexagramNumber":34,"typeKey":"ESTJ-calm-autonomous","title":"有度推進者","src":"./assets/personality/hexagram-34.webp","width":1254,"height":1254,"conceptZh":"執行者把力量接到有邊界的木製推進裝置，手掌主動停在閘門前核對，遠處雷雲只是動勢。強勁與節制同時成立。","sha256":"ef833964439848486c91953082d9210415c9a1cc1099975f41c3aff5c8e7c706"},"35":{"hexagramNumber":35,"typeKey":"ESTP-sensitive-cooperative","title":"共行見曉者","src":"./assets/personality/hexagram-35.webp","width":1254,"height":1254,"conceptZh":"兩位夥伴一起完成面向晨光的低平台，同時回顧固定支撐與實作成果。以地上出明連結現場應變與共享貢獻。","sha256":"02a28c691b9c53eb6b46060b3089e806042918f712a4d7b86bda44ecf2848064"},"36":{"hexagramNumber":36,"typeKey":"INFJ-sensitive-autonomous","title":"藏光護念者","src":"./assets/personality/hexagram-36.webp","width":1254,"height":1254,"conceptZh":"創作者在土色拱廊下保護小燈，另一端的開口讓光有安全的出口。以明入地中表現信念的保存與選擇表達時機，避免受難或被囚意象。","sha256":"df1796399db1fc15a17fd5aac85288b11407c73738e55a15756b037779d4e05f"},"37":{"hexagramNumber":37,"typeKey":"ISTJ-calm-cooperative","title":"共築日常者","src":"./assets/personality/hexagram-37.webp","width":1254,"height":1254,"conceptZh":"兩位夥伴在日常共用桌前調整可拆換的木格與器物位置，風從小火爐上方的開窗流過。以共同協商維持可靠日常，不指定家庭或性別角色。","sha256":"0a24eafc3fa7a291e4a53a4f382c1501dead5b5677f428d8ea0dc6f8ff155edf"},"38":{"hexagramNumber":38,"typeKey":"ENTP-calm-autonomous","title":"異路探問者","src":"./assets/personality/hexagram-38.webp","width":1254,"height":1254,"conceptZh":"探問者在上方暖光與下方水澤之間測試兩種不同小橋，讓不同路徑仍接到共同的平台。以睽表現差異中的小尺度驗證。","sha256":"44f167a475d12a536a503f46ad80fc4c7c04b01e7f3fad9d04e7b6bca3c8e087"},"39":{"hexagramNumber":39,"typeKey":"ISTJ-sensitive-cooperative","title":"聯手越嶺者","src":"./assets/personality/hexagram-39.webp","width":1254,"height":1254,"conceptZh":"兩位行者面對山前積水，一起查看安全落腳點並握持同一條鬆繩。停下核對與接受支援，是共同越嶺的實際能力。","sha256":"2357b3604e9ef63b34c328f48e3922273832fd90de5384fffab72f72453e3c86"},"40":{"hexagramNumber":40,"typeKey":"ISTP-calm-cooperative","title":"解結共修者","src":"./assets/personality/hexagram-40.webp","width":1254,"height":1254,"conceptZh":"兩位修理者先交換看法，再解開卡住水輪的繩結。雨後水道重新流動，連結解卦的鬆動與可使用的實際解法。","sha256":"13f28603d075bc98bf50f8c2bf9bcc8db0a4f24a69d428bdf4c625e06a10439f"},"41":{"hexagramNumber":41,"typeKey":"ISFJ-sensitive-cooperative","title":"知量共養者","src":"./assets/personality/hexagram-41.webp","width":1254,"height":1254,"conceptZh":"照料者與夥伴共同衡量有限的水，留下自己休息用的一杯而非全部倒出。以山下有澤與適量滋養表現界線及平等分工。","sha256":"c4670bf3079849d1a2e8890a0e5eb2fde798fc0899cb9aa910575e50c8610435"},"42":{"hexagramNumber":42,"typeKey":"ENFJ-sensitive-cooperative","title":"互益引路者","src":"./assets/personality/hexagram-42.webp","width":1254,"height":1254,"conceptZh":"兩位共同培育者把小水渠分向不同高度的苗木，各自調整而非強迫同步成長。以風雷的動能表現支持流動與共同受益。","sha256":"f1d6892e8a57568ba3e151cb1df17946dedd1bd7a4bf30fd4c554fdfd81f567a"},"43":{"hexagramNumber":43,"typeKey":"ENTJ-sensitive-autonomous","title":"明言開路者","src":"./assets/personality/hexagram-43.webp","width":1254,"height":1254,"conceptZh":"發起者把已有的方案放上開放的平台，手勢留出回應的方向；上方水澤意象保留在雲與水盆中。果斷伴隨公開理由與可回應的空間。","sha256":"cce8530b9cc6f9e7352ab58f77c3085bb67514dad3d5503001a6930083868a9d"},"44":{"hexagramNumber":44,"typeKey":"ENFP-sensitive-autonomous","title":"遇風尋路者","src":"./assets/personality/hexagram-44.webp","width":1254,"height":1254,"conceptZh":"探索者在半開門前接住風送來的種莢，另一手仍握著門緣調整開度。姤的相遇帶來想像，也保有選擇承諾的自主節奏。","sha256":"9de0d5a7a8d041cd1f5bb2a47389e59839846504313e423e3522153937a9a604"},"45":{"hexagramNumber":45,"typeKey":"ESFJ-sensitive-cooperative","title":"聚心成席者","src":"./assets/personality/hexagram-45.webp","width":1254,"height":1254,"conceptZh":"兩位籌備者把座席圍成開口的圓，保留可自由加入或離開的位置。澤上於地的聚集意象，轉成容納不同聲音的共同場合。","sha256":"dc07e3135842942123a9629a5e3302531fdd84c0c1a7b6d3326b4bd0e68229bb"},"46":{"hexagramNumber":46,"typeKey":"ENFP-calm-cooperative","title":"共栽新枝者","src":"./assets/personality/hexagram-46.webp","width":1254,"height":1254,"conceptZh":"兩位夥伴共同把幼木安置到土中，支架可以調整，枝條向上留有空間。升的地中生木成為耐心陪伴、持續照料的原創比喻。","sha256":"d6ad83675854b59b352e2a2c45513189abc5ace03246cabad144cad232ed9927"},"47":{"hexagramNumber":47,"typeKey":"ISTP-sensitive-autonomous","title":"限中尋徑者","src":"./assets/personality/hexagram-47.webp","width":1254,"height":1254,"conceptZh":"受限的修理者在乾淺水池旁試做竹管，取用眼前有限材料並把開口朝外，讓限制可被看見、協助有入口。困不作命運或失敗標籤。","sha256":"c1ddeea7e3cb02f1c84688ed2fd2527bc116d9a991e9fa60f130cecc06588407"},"48":{"hexagramNumber":48,"typeKey":"INTP-calm-cooperative","title":"共汲知泉者","src":"./assets/personality/hexagram-48.webp","width":1254,"height":1254,"conceptZh":"兩位思考者把井水汲入形狀不同、皆可使用的容器，順便調整井口高度。知識的深度須透過可理解的入口成為共同資源。","sha256":"9146152a9fe3c6cc6f924a0603c638b44723e5ebecc2f434309525959a14df51"},"49":{"hexagramNumber":49,"typeKey":"ENTJ-sensitive-cooperative","title":"共議革新者","src":"./assets/personality/hexagram-49.webp","width":1254,"height":1254,"conceptZh":"兩位改革者把磨損結構拆成可重組的木件，邊比較舊件與新接點邊共同定案。以革表現時機、信任與受影響者參與的更新。","sha256":"55ff803818325aba08c668b879174812d0b72a16482f65947ea03291638b985d"},"50":{"hexagramNumber":50,"typeKey":"INTJ-calm-cooperative","title":"共煉新器者","src":"./assets/personality/hexagram-50.webp","width":1254,"height":1254,"conceptZh":"兩位設計者一同檢查原創三足器的把手與受力，材料在適度熱源中轉成共享滋養。鼎是能維護、能使用的共同系統，非照摹任何館藏器物。","sha256":"5903e9d7e72824b7d17f8de612b50476d9a21447bf13bf332f0bc4eff1bbc124"},"51":{"hexagramNumber":51,"typeKey":"ENTP-sensitive-autonomous","title":"驚中試新者","src":"./assets/personality/hexagram-51.webp","width":1254,"height":1254,"conceptZh":"突發雷聲使探索者暫停手上的小原型，先以簡單實物確認新想法。震的驚動與好奇並存，但畫面保留核對事實的短暫停頓。","sha256":"45b11a66ae2f6f78b63623f95f6bb316760507411ca2121173176091edc0c463"},"52":{"hexagramNumber":52,"typeKey":"INTP-calm-autonomous","title":"止處深思者","src":"./assets/personality/hexagram-52.webp","width":1254,"height":1254,"conceptZh":"獨處思考者在雙重山勢前把問題縮到一盤幾何木件，空出一塊待測位置。艮的止處提供可站穩的範圍，旁邊的小徑仍朝外延伸。","sha256":"13ab7afa9083c55fa0b2c11c9d37b600953b590bb9b783f64634a03cad6bd7e6"},"53":{"hexagramNumber":53,"typeKey":"INFJ-calm-cooperative","title":"同行漸成者","src":"./assets/personality/hexagram-53.webp","width":1254,"height":1254,"conceptZh":"兩位同行者在山坡幼樹旁，把可移動小踏步調到共同可走的間距。漸的山上有木連結長期願景、耐心與看得見的階段。","sha256":"f8fc9cb8ad91a75de86aca29bf21e37763509c8940e87ca6a62b55c0bb3a4447"},"54":{"hexagramNumber":54,"typeKey":"ESFJ-sensitive-autonomous","title":"擇約守心者","src":"./assets/personality/hexagram-54.webp","width":1254,"height":1254,"conceptZh":"主動照顧者在湖畔整理自己的座席與空白邀請物件，保留可選擇的入口。以歸妹檢視關係位置的課題，轉成平等同意與加入前的自我確認。","sha256":"0b1668446a03758285b9df2a215eb5d6f036f4f9567685d8e8ca70bad401875a"},"55":{"hexagramNumber":55,"typeKey":"ESFP-sensitive-autonomous","title":"盛時點光者","src":"./assets/personality/hexagram-55.webp","width":1254,"height":1254,"conceptZh":"表達者把豐盛的當下化為一盞自己完成的紙燈，桌旁留一張休息凳和收納盒。雷電皆至的飽滿轉成精彩與收尾並存的日常場景。","sha256":"dfc81f35ac3f6e842260324adb17fa3fd7fbf0cf7060b0a6687dbeec6d1bf195"},"56":{"hexagramNumber":56,"typeKey":"ENFP-calm-autonomous","title":"行旅拾意者","src":"./assets/personality/hexagram-56.webp","width":1254,"height":1254,"conceptZh":"旅人停在陌生山路上的開放驛亭，先整理行囊、觀察所在環境再選路。小火光照亮可返回的小徑，表現自由與連結共存。","sha256":"44b75b4166d7281f9d8ec1cff953c1be9a1343d24b9fce39edbf43a951c6d206"},"57":{"hexagramNumber":57,"typeKey":"ISFP-sensitive-cooperative","title":"柔風共作人","src":"./assets/personality/hexagram-57.webp","width":1254,"height":1254,"conceptZh":"兩位創作者在柔風吹動的布幔旁共修一件作品，一方示意自己的選色，另一方調整材料。風的漸入日常包含互相聽見，而非單方順從。","sha256":"f701b472b89d47dc5ebdb0b5bea24ab9935e995067fdf258f9133595438e0f4e"},"58":{"hexagramNumber":58,"typeKey":"ESFP-sensitive-cooperative","title":"歡語共學者","src":"./assets/personality/hexagram-58.webp","width":1254,"height":1254,"conceptZh":"兩位朋友在相連水澤旁分享小型手作體驗，一張空凳也歡迎安靜參與。兌的喜悅與共學保留真誠差異，不要求每個人表情一致。","sha256":"c7719e5e865976de1873cbf226f9cfa301fa0c8b7120227188f5a049fb599f47"},"59":{"hexagramNumber":59,"typeKey":"ENFP-sensitive-cooperative","title":"散結連橋者","src":"./assets/personality/hexagram-59.webp","width":1254,"height":1254,"conceptZh":"兩位連結者在水邊把散開的繩索重新接成鬆而可靠的小橋，留下各自岸邊的空間。風行水上的渙，轉為釐清隔閡與自由連結。","sha256":"4517b11c3ee9be2b19938775b3bf940e110bd97034601c48ee88064fc24cacd4"},"60":{"hexagramNumber":60,"typeKey":"ISTJ-sensitive-autonomous","title":"定度守衡者","src":"./assets/personality/hexagram-60.webp","width":1254,"height":1254,"conceptZh":"規劃者為湖邊水槽調整可拆換的木製水閘，保留一個溢流出口。節的尺度服務生活，規則可隨條件改變而重新衡量。","sha256":"2a33d84d16b652ef83041506b4ed5f36db2d1eebc90b28d01c9ce20b54e9a556"},"61":{"hexagramNumber":61,"typeKey":"INFJ-sensitive-cooperative","title":"誠聲相和者","src":"./assets/personality/hexagram-61.webp","width":1254,"height":1254,"conceptZh":"兩位對話者在有風的水邊，各自把一塊透明器物放到同一個可見位置，確認彼此所指。遠處一對水鳥呼應，真誠透過可核對的表達建立信任。","sha256":"603cd74575de781a9b6651301913e56af2745255c4b3777c0505e1f3461cbc87"},"62":{"hexagramNumber":62,"typeKey":"ISFJ-sensitive-autonomous","title":"細步護行者","src":"./assets/personality/hexagram-62.webp","width":1254,"height":1254,"conceptZh":"照料者在低矮山徑邊先修一級容易踩空的小踏步，再查看自己剩餘材料。低飛小鳥呼應小過的小步與適度，不把周到畫成無限責任。","sha256":"f835f37763b50ef5af994087a69dc07ee8efc1e30ecb400645294b7d239d0eba"},"63":{"hexagramNumber":63,"typeKey":"ESTJ-sensitive-cooperative","title":"共守成局者","src":"./assets/personality/hexagram-63.webp","width":1254,"height":1254,"conceptZh":"兩位維護者在已可使用的茶水裝置旁核對接點與交接，水在有節制的小火上方。既濟的完成是一個需要共同照料的階段。","sha256":"580bce7367b04a97bb9d0476de6ad49c09e194e3709022566090e7fe45a24cf4"},"64":{"hexagramNumber":64,"typeKey":"INTP-sensitive-cooperative","title":"共辨未來者","src":"./assets/personality/hexagram-64.webp","width":1254,"height":1254,"conceptZh":"兩位探索者在尚未接上的水上小橋前，先把可用與待測木件分置兩盤，準備下一個可驗證落腳點。未濟的開放性有清楚界線與共同實作。","sha256":"8c58655589fa12eccb60ed7afd5d62e4898b99292632f6631f25adab6c56ecbb"}};
